import { BaseElement } from '../../common/base-element';
import { FACETS, LEVEL_DESCS, LEVEL_IMAGES, type FacetId } from './data';
import {
  answer, computeResult, estimateMaxSteps, goBack, newState, Q_MAP, startQuestionnaire, toggleFacet, type State,
} from './questionnaire';
import { ratingStyles } from './styles';

/**
 * <rg-real-rating>: the REAL Rating Questionnaire. The visitor ticks the components of their work
 * (visuals, audio, text), answers a few yes/no questions about generative AI, and gets a rating from
 * 0 to 5. Everything happens in the page: nothing is sent or stored.
 *
 * The markup, wording and styles are the original widget's; the question logic is in
 * questionnaire.ts (tested against the original on every possible sequence of answers).
 */
export class RgRealRating extends BaseElement {
  private state: State = newState();

  constructor() {
    super(ratingStyles);
    // One delegated listener instead of the original's inline onclick attributes.
    this.root.addEventListener('click', (e) => {
      const el = (e.target as HTMLElement).closest<HTMLElement>('[data-action]');
      if (!el) return;
      switch (el.dataset.action) {
        case 'toggle':
          toggleFacet(this.state, el.dataset.id as FacetId);
          break;
        case 'start':
          startQuestionnaire(this.state);
          break;
        case 'yes':
        case 'no':
          answer(this.state, el.dataset.action);
          break;
        case 'back':
          goBack(this.state);
          break;
        case 'restart':
          this.state = newState();
          break;
        default:
          return;
      }
      this.render();
    });
  }

  connectedCallback(): void {
    this.setHtml(`
<div id="rr-widget">
  <div class="rr-header">
    <h2>REAL Rating Questionnaire</h2>
    <p>Select all the components in your work, then answer a few questions</p>
  </div>
  <div id="rr-screen"></div>
</div>`);
    this.render();
  }

  private render(): void {
    const screen = this.$('#rr-screen');
    if (!screen) return;
    if (this.state.phase === 'select') screen.innerHTML = this.selectHtml();
    else if (this.state.phase === 'question') screen.innerHTML = this.questionHtml();
    else screen.innerHTML = this.resultHtml();
  }

  private selectHtml(): string {
    const s = this.state;
    const canStart = s.selected.length > 0;
    return `
    <div class="rr-facet-grid">
      ${FACETS.map(
        (f) => `
        <button class="rr-facet-btn${s.selected.includes(f.id) ? ' selected' : ''}"
                data-action="toggle" data-id="${f.id}">
          <span class="rr-facet-check"></span>
          <span class="rr-facet-icon">${f.icon}</span>
          <span class="rr-facet-label">${f.label}</span>
          <span class="rr-facet-sub">${f.sub}</span>
        </button>
      `,
      ).join('')}
    </div>
    <button class="rr-start-btn" data-action="start" ${canStart ? '' : 'disabled'}>
      ${canStart ? 'Start questionnaire →' : 'Select at least one component'}
    </button>
  `;
  }

  private questionHtml(): string {
    const s = this.state;
    const q = Q_MAP[s.qid as string];
    const maxSteps = estimateMaxSteps(s);
    const progress = Math.min(s.history.length, maxSteps);

    const chips = FACETS.filter((f) => s.selected.includes(f.id))
      .map((f) => {
        const isActive = q.applicableTo && q.applicableTo.includes(f.id);
        return `<span class="rr-chip${isActive ? ' active' : ''}">${f.icon} ${f.label}</span>`;
      })
      .join('');

    const dots = Array.from({ length: maxSteps }, (_, i) => `<div class="rr-dot${i < progress ? ' done' : ''}"></div>`).join('');

    return `
    <div class="rr-card">
      <div class="rr-chips">${chips}</div>
      <div class="rr-progress">${dots}</div>
      <div class="rr-question">${q.text}</div>
      ${q.context ? `<div class="rr-q-context">${q.context}</div>` : ''}
      <div class="rr-btn-group">
        <button class="rr-answer-btn" data-action="yes">Yes</button>
        <button class="rr-answer-btn" data-action="no">No</button>
      </div>
      ${s.history.length > 0 ? '<button class="rr-back-btn" data-action="back">← Back</button>' : ''}
    </div>
    <div class="rr-footer">
      <button class="rr-restart-btn" data-action="restart">↩ Restart</button>
    </div>
  `;
  }

  private resultHtml(): string {
    const { facets, overall, highest } = computeResult(this.state);
    const breakdown =
      facets.length > 1
        ? `
    <div class="rr-breakdown">
      ${facets
        .map(
          (f) => `
        <div class="rr-breakdown-item${highest.includes(f.id) ? ' highest' : ''}">
          <span class="rr-breakdown-icon">${f.icon}</span>
          <span class="rr-breakdown-facet">${f.label}</span>
          <span class="rr-breakdown-score">${f.score}</span>
        </div>
      `,
        )
        .join('')}
    </div>
  `
        : '';

    return `
    <div class="rr-card rr-result">
      <p class="rr-result-overall-label">Your REAL Rating</p>
      <img class="rr-result-img" src="${LEVEL_IMAGES[overall]}" alt="REAL Rating Level ${overall}" />
      <p class="rr-result-desc">${LEVEL_DESCS[overall]}</p>
      ${breakdown}
      <button class="rr-restart-btn" data-action="restart">↩ Start Over</button>
    </div>
  `;
  }
}

if (!customElements.get('rg-real-rating')) customElements.define('rg-real-rating', RgRealRating);
