// The REAL rating questionnaire's engine: a port of the original widget's logic, function for function
// (it mutates a state object in place exactly as the original did). The tests walk EVERY possible
// sequence of answers for every selection of facets and compare the outcome with the original
// engine's (see questionnaire.test.ts), so do not "simplify" this without rerunning them.
//
// Scoring: each selected facet starts at 0; answers raise a facet's score to at least a level (never
// lower); the final rating is the highest facet score.

import { FACETS, QUESTIONS, type Branch, type FacetId, type Question } from './data';

export type Phase = 'select' | 'question' | 'result';

export interface State {
  phase: Phase;
  /** The facets the visitor ticked, in the order they were ticked. */
  selected: FacetId[];
  /** The question being shown. */
  qid: string | null;
  scores: Partial<Record<FacetId, number>>;
  /** One entry per answered question, so "Back" can undo it. */
  history: Array<{ qid: string; scores: Partial<Record<FacetId, number>> }>;
}

export const Q_MAP: Record<string, Question> = {};
QUESTIONS.forEach((q) => {
  Q_MAP[q.id] = q;
});

export function newState(): State {
  return { phase: 'select', selected: [], qid: null, scores: {}, history: [] };
}

function facetApplies(state: State, q: Question): boolean {
  if (!q.applicableTo) return true;
  // _autoOnly: skip if the named facet already scored >= 2 (it is on the AI track)
  if (q._autoOnly) {
    const f = q._autoOnly;
    if (!state.selected.includes(f)) return false;
    if ((state.scores[f] || 0) >= 2) return false;
    return true;
  }
  return q.applicableTo.some((f) => state.selected.includes(f));
}

/** Resolve routers and skip questions that do not apply. Returns the first question id that applies, or "DONE". */
function resolveNext(state: State, id: string | undefined): string {
  if (!id || id === 'DONE') return 'DONE';
  const q = Q_MAP[id];
  if (!q) return 'DONE';

  if (q._router) {
    for (const target of q.route ?? []) {
      const tq = Q_MAP[target];
      if (tq && facetApplies(state, tq)) return resolveNext(state, target);
    }
    return 'DONE';
  }

  if (!facetApplies(state, q)) {
    // Skip this question: go to wherever "no" would go (a neutral skip)
    const skip = q.no;
    const nextId = typeof skip === 'object' ? skip.next : skip;
    return resolveNext(state, nextId);
  }

  return id;
}

function applySet(state: State, setObj: Partial<Record<FacetId, number>> | undefined): void {
  if (!setObj) return;
  for (const [facet, score] of Object.entries(setObj) as Array<[FacetId, number]>) {
    if (state.selected.includes(facet)) {
      // floor: only raise, never lower
      state.scores[facet] = Math.max(state.scores[facet] || 0, score);
    }
  }
}

/** Answer the current question. */
export function answer(state: State, yn: 'yes' | 'no'): void {
  const q = Q_MAP[state.qid as string];
  const branch: Branch | undefined = q[yn];

  // Save a snapshot for "Back"
  state.history.push({ qid: state.qid as string, scores: { ...state.scores } });

  if (branch && typeof branch === 'object' && branch.set) applySet(state, branch.set);

  const nextId = branch && typeof branch === 'object' ? branch.next : branch;
  const resolved = resolveNext(state, nextId);

  if (resolved === 'DONE') {
    // Fill in 0 for any facet that never got a score
    state.selected.forEach((f) => {
      if (!(f in state.scores)) state.scores[f] = 0;
    });
    state.phase = 'result';
  } else {
    state.qid = resolved;
  }
}

export function goBack(state: State): void {
  if (!state.history.length) return;
  const snap = state.history.pop()!;
  state.qid = snap.qid;
  state.scores = { ...snap.scores };
  state.phase = 'question';
}

export function startQuestionnaire(state: State): void {
  if (!state.selected.length) return;
  const scores: Partial<Record<FacetId, number>> = {};
  state.selected.forEach((f) => (scores[f] = 0));
  state.scores = scores;
  state.history = [];
  const first = resolveNext(state, 'q_ai_prompt');
  state.qid = first;
  state.phase = first === 'DONE' ? 'result' : 'question';
}

export function toggleFacet(state: State, id: FacetId): void {
  const idx = state.selected.indexOf(id);
  if (idx === -1) state.selected.push(id);
  else state.selected.splice(idx, 1);
}

/**
 * The progress bar's length: the worst-case number of questions (2 shared ones plus 3 per facet), so the
 * bar never overflows.
 */
export function estimateMaxSteps(state: State): number {
  return 2 + state.selected.length * 3;
}

export interface Result {
  facets: Array<{ id: FacetId; label: string; sub: string; icon: string; score: number }>;
  overall: number;
  highest: FacetId[];
}

export function computeResult(state: State): Result {
  const facets = state.selected.map((id) => {
    const f = FACETS.find((x) => x.id === id)!;
    return { ...f, score: state.scores[id] || 0 };
  });
  const overall = Math.max(...facets.map((f) => f.score));
  return { facets, overall, highest: facets.filter((f) => f.score === overall).map((f) => f.id) };
}
