// The REAL rating questionnaire's data, copied verbatim from the original widget (do not retype):
// the level images and descriptions, the three facets, and the question graph.
// The engine that walks the graph is in questionnaire.ts.

export type FacetId = 'visuals' | 'audio' | 'text';

export interface Facet {
  id: FacetId;
  label: string;
  sub: string;
  icon: string;
}

/** What an answer does: raise some facets' scores to at least a level, then go to the next question. */
export type Branch = string | { set?: Partial<Record<FacetId, number>>; next: string };

export interface Question {
  id: string;
  text?: string;
  context?: string | null;
  applicableTo?: FacetId[];
  yes?: Branch;
  no?: Branch;
  /** A router is never shown: it picks the first of `route` that applies. */
  _router?: boolean;
  route?: string[];
  /** Skip this question if the named facet already scored 2 or more (it is on the AI track). */
  _autoOnly?: FacetId;
}

